effect.shader:
void main() {
    ivec2 T = textureSize(inputImg, 0);
    vec4 c = texelFetch(inputImg, ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0)), 0);
    float y = dot(c.rgb, vec3(0.299, 0.587, 0.114));
    vec3 cor = y < 0.5 ? mix(shadows.rgb, midtones.rgb, clamp(y * 2.0, 0.0, 1.0))
                       : mix(midtones.rgb, highlights.rgb, clamp(y * 2.0 - 1.0, 0.0, 1.0));
    fragColor = vec4(mix(cor, c.rgb, clamp(blendWithOriginal / 100.0, 0.0, 1.0)), c.a);
}
